#!/usr/bin/env bash
# Runs in the work dir after the last turn; prints one JSON object of named
# booleans. Generated by bench/search_fixtures.py: the expected answer was
# computed from the tracked files of the fixture, not written by hand.
exec "${BENCH_PYTHON:-python3}" - <<'PY'
import json, os, re, subprocess, sys
from pathlib import Path

EXPECTED = json.loads('{"answer": "pkg/uploads/limits.py:check_upload_quota", "all_raisers": ["pkg/sync/limits.py:check_sync_quota", "pkg/uploads/limits.py:check_upload_quota"]}')
a = Path("answer.txt").read_text().split() if Path("answer.txt").exists() else []
got = a[0].strip("`") if a else ""
print(json.dumps({"answered": bool(got), "correct": got == EXPECTED["answer"]}))
PY
